// Release-candidate neutrality smoke (rc1): a NORMAL customer (not on the preview list) with one Minecraft game server,
// plus one admin, on devhost's throwaway DB. No Cyrus setting is written: every Cyrus flag stays at its default.
// Prints session tokens (throwaway AUTH_SECRET) as JSON for rc-neutral-shots.mjs. Refuses any other database.
//   devhost db push && devhost run -- npx tsx prisma/seed.ts
//   devhost run -- npx tsx scripts/cyrus/rc-neutral-fixtures.ts > .rc-tokens.json
import { SignJWT } from "jose";
import { db } from "../../lib/db";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }
const secret = new TextEncoder().encode(process.env.AUTH_SECRET ?? "");

async function main() {
  const people = [
    { id: "usr_rc_customer", email: "customer@rc.example.test", role: "CUSTOMER" },
    { id: "usr_rc_admin", email: "admin@rc.example.test", role: "ADMIN" },
  ];
  for (const p of people)
    await db.user.upsert({ where: { id: p.id }, update: {}, create: { id: p.id, email: p.email, name: p.email.split("@")[0], role: p.role, passwordHash: "x", emailVerifiedAt: new Date(), heardAboutUs: "other" } as never });
  const plan = await db.plan.upsert({ where: { slug: "rcfx" }, create: { slug: "rcfx", name: "rc", cpuCores: 2, ramMB: 4096, diskGB: 30, priceCents: 1 }, update: {} });
  const os = await db.osTemplate.upsert({ where: { slug: "rcfx-mc" }, create: { slug: "rcfx-mc", name: "Minecraft", vmid: 1, family: "minecraft" }, update: {} });
  const gp = (await db.gamePlan.findFirst({ where: { name: "rcfx" } })) ?? (await db.gamePlan.create({ data: { gameFamily: "minecraft", name: "rcfx", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 1, basePlanId: plan.id } as never }));
  const srv = (await db.server.findFirst({ where: { userId: "usr_rc_customer", name: "rc-survival" } })) ??
    (await db.server.create({ data: { name: "rc-survival", hostname: "rc-survival.test", userId: "usr_rc_customer", planId: plan.id, osTemplateId: os.id, gamePlanId: gp.id, status: "RUNNING", gameVariant: "paper", gameConfig: { VERSION: "1.21.11" } } as never }));
  const out: Record<string, unknown> = { server: srv.id, cookie: process.env.NXEON_COOKIE_NAME ?? "nxeon_session" };
  for (const p of people) {
    const u = await db.user.findUniqueOrThrow({ where: { id: p.id } });
    out[p.role.toLowerCase()] = await new SignJWT({ sub: u.id, sv: u.sessionVersion ?? 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("6h").sign(secret);
  }
  console.log(JSON.stringify(out));
}
main().then(() => process.exit(0), (e) => { console.error(e); process.exit(1); });
EOF
cat > /tank/dev-worktrees/cyrus-rc1/scripts/cyrus/rc-neutral-shots.mjs <<'EOF'
// Release-candidate neutrality smoke (rc1), run ON node-2 against a `next start` of a build with every Cyrus flag off:
// normal-customer and admin pages answer, carry no Cyrus UI, and are screenshotted for a side-by-side with main.
//   devhost run -- env BASE=http://127.0.0.1:<port> TOKENS=.rc-tokens.json OUT=impl-shots TAG=rc node scripts/cyrus/rc-neutral-shots.mjs
import { chromium } from "playwright";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".rc-tokens.json", "utf8"));
const OUT = process.env.OUT ?? "impl-shots", TAG = process.env.TAG ?? "rc";
mkdirSync(OUT, { recursive: true });
const pages = [
  ["home", "/", null], ["login", "/login", null], ["pricing", "/game-servers", null],
  ["dashboard", "/dashboard", "customer"], ["server", `/dashboard/servers/${tok.server}`, "customer"],
  ["deploy", "/dashboard/deploy", "customer"], ["billing", "/dashboard/billing", "customer"],
  ["mods-cyrus", "/dashboard/cyrus", "customer"], ["admin", "/admin", "admin"],
];
const b = await chromium.launch();
const report = [];
for (const [name, path, who] of pages) {
  const ctx = await b.newContext({ viewport: { width: 1440, height: 900 } });
  const cookies = [{ name: "nxeon_cookie_consent", value: "all", url: BASE }];
  if (who) cookies.push({ name: tok.cookie, value: tok[who], url: BASE });
  await ctx.addCookies(cookies);
  const page = await ctx.newPage();
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));
  const res = await page.goto(BASE + path, { waitUntil: "load", timeout: 240000 }).catch((e) => { errs.push("goto " + e); return null; });
  await page.waitForTimeout(2500);
  const text = (await page.evaluate(() => document.body?.innerText ?? "").catch(() => "")) || "";
  const cyrusMentions = (text.match(/cyrus/gi) || []).length;
  await page.screenshot({ path: `${OUT}/${TAG}-${name}.png`, fullPage: false }).catch(() => {});
  report.push({ name, path, who, status: res?.status() ?? 0, finalUrl: page.url().replace(BASE, ""), cyrusMentions, errors: errs });
  await ctx.close();
}
await b.close();
writeFileSync(`${OUT}/${TAG}-report.json`, JSON.stringify(report, null, 1));
for (const r of report) console.log(`${r.status} ${r.name.padEnd(11)} ${r.finalUrl.padEnd(40)} cyrus=${r.cyrusMentions} errors=${r.errors.length}`);
EOF
echo ok

